window.SGBY_ALLOC_ALL=function(t){
  const city=Dn.g_Cities[t];
  if(!city)return{ok:0,reason:"no-city"};
  const list=ss(t);
  if(!list.length)return{ok:0,reason:"no-person"};
  const before=city.MothballArms;
  let n=0,add=0,full=0;
  for(let i=0;i<list.length;i++){
    const p=Dn.g_Persons[list[i]];
    let cap=10*(10*p.Level+p.Force+p.IQ);
    if(cap>city.MothballArms+p.Arms)cap=city.MothballArms+p.Arms;
    if(cap===p.Arms){full+=1;continue}
    add+=cap-p.Arms;
    city.MothballArms=city.MothballArms+p.Arms-cap;
    p.Arms=cap;n+=1;
    if(city.MothballArms<=0)break
  }
  try{l.screen.markDirty()}catch(e){}
  return{ok:1,persons:n,full:full,added:add,before:before,left:city.MothballArms}};

window.SGBY_FEAST_ALL=function(t){
  const city=Dn.g_Cities[t];
  if(!city)return{ok:0,reason:"no-city"};
  const list=ss(t);
  if(!list.length)return{ok:0,reason:"no-person"};
  const COST=Ge[12];
  const before=city.Money;
  let n=0;
  for(let i=0;i<list.length;i++){
    if(city.Money<COST)break;
    const p=Dn.g_Persons[list[i]];
    city.Money-=COST;
    p.Thew+=50;p.Thew>100&&(p.Thew=100);
    list[i]!==Dn.g_PlayerKing&&p.Devotion<100&&(p.Devotion+=1);
    n+=1
  }
  try{l.screen.markDirty()}catch(e){}
  return{ok:1,persons:n,before:before,left:city.Money,cost:COST}};

